package binlogviz

import (
	"bytes"
	"encoding/json"
	"html"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"binlogviz/internal/jsonschema"
)

// docs/examples holds the sample reports the quickstart points operators at.
// They are generated by a real analyze of the committed fixture and must not
// drift from what the binary prints today: every format must be byte-identical
// to a fresh run, and the JSON must satisfy the shipped analyze schema.
// UPDATE_EXAMPLES=1 regenerates them.
//
// The landing page shows the same three reports in its output previews. They
// were hand-written once and drifted into sections that did not exist, so a
// preview must be a verbatim slice of the pinned example and both dictionaries
// must carry that same text.
func TestExampleOutputsMatchFreshRun(t *testing.T) {
	forceEnglishRuntimeOutput(t)
	root := repoRoot(t)
	t.Chdir(root)
	rel := "cmd/binlogviz/testdata/minimal.binlog"
	for _, tc := range []struct {
		format string
		file   string
	}{
		{"json", "analyze-output.json"},
		{"text", "analyze-output.txt"},
		{"markdown", "analyze-output.md"},
	} {
		code, stdout, stderr := runRoot(t, "analyze", rel, "--format", tc.format)
		if code != 0 {
			t.Fatalf("analyze --format %s: exit %d: %s", tc.format, code, stderr)
		}
		// mysqlbinlog_cmd embeds the absolute fixture path; pin the relative
		// form so the example is the same on every checkout.
		if abs, err := filepath.Abs(rel); err == nil {
			stdout = strings.ReplaceAll(stdout, abs, rel)
		}
		path := filepath.Join(root, "docs", "examples", tc.file)
		if os.Getenv("UPDATE_EXAMPLES") == "1" {
			if err := os.WriteFile(path, []byte(stdout), 0o644); err != nil {
				t.Fatal(err)
			}
		}
		checked, err := os.ReadFile(path)
		if err != nil {
			t.Fatalf("read %s (UPDATE_EXAMPLES=1 rewrites it): %v", path, err)
		}
		if !bytes.Equal(checked, []byte(stdout)) {
			t.Errorf("docs/examples/%s differs from a fresh run; UPDATE_EXAMPLES=1 regenerates it", tc.file)
		}
		if tc.format == "json" {
			var inst any
			if err := json.Unmarshal(checked, &inst); err != nil {
				t.Fatal(err)
			}
			if err := jsonschema.Validate(readPublishedSchema(t, root, "analyze"), inst); err != nil {
				t.Errorf("docs/examples/%s fails docs/schema/analyze.json: %v", tc.file, err)
			}
		}
	}
}

// TestLandingPreviewsAreRealOutput holds the landing page's output panes to the
// pinned examples: a reader comparing the page with their own run must not find
// invented section names or field names.
func TestLandingPreviewsAreRealOutput(t *testing.T) {
	root := repoRoot(t)
	page, err := os.ReadFile(filepath.Join(root, "docs", "landing", "index.html"))
	if err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct{ key, file string }{
		{"outputs.previewBodies.text", "analyze-output.txt"},
		{"outputs.previewBodies.json", "analyze-output.json"},
		{"outputs.previewBodies.markdown", "analyze-output.md"},
	} {
		example, err := os.ReadFile(filepath.Join(root, "docs", "examples", tc.file))
		if err != nil {
			t.Fatal(err)
		}
		pane := landingPaneBody(t, string(page), tc.key)
		if pane == "" {
			t.Fatalf("%s: the pane has no text", tc.key)
		}
		if !strings.Contains(string(example), pane) {
			t.Errorf("docs/landing/index.html %s is not a verbatim slice of docs/examples/%s; paste the real output", tc.key, tc.file)
		}
		for _, dict := range []string{"en", "zh-CN"} {
			value, ok := landingDictValue(t, string(page), dict, tc.key)
			if !ok {
				t.Fatalf("%s: the %s dictionary has no value", tc.key, dict)
			}
			if value != pane {
				t.Errorf("%s: the %s dictionary differs from the pane; both must carry the same real output", tc.key, dict)
			}
		}
	}
}

// landingPaneBody returns the visible text of <pre data-i18n="key">…</pre>.
func landingPaneBody(t *testing.T, page, key string) string {
	t.Helper()
	open := `<pre data-i18n="` + key + `">`
	i := strings.Index(page, open)
	if i < 0 {
		t.Fatalf("%s: no pane", key)
	}
	rest := page[i+len(open):]
	j := strings.Index(rest, "</pre>")
	if j < 0 {
		t.Fatalf("%s: the pane never closes", key)
	}
	body := html.UnescapeString(rest[:j])
	return strings.TrimRight(stripTags(body), "\n")
}

// landingDictValue reads one single-quoted dictionary string and unescapes it.
func landingDictValue(t *testing.T, page, dict, key string) (string, bool) {
	t.Helper()
	header := "        " + dict + ": {"
	if dict == "zh-CN" {
		header = "        'zh-CN': {"
	}
	start := strings.Index(page, header)
	if start < 0 {
		return "", false
	}
	section := page[start:]
	block := strings.Index(section, "previewBodies: {")
	if block < 0 {
		return "", false
	}
	section = section[block:]
	leaf := key[strings.LastIndex(key, ".")+1:]
	at := strings.Index(section, leaf+": '")
	if at < 0 {
		return "", false
	}
	rest := section[at+len(leaf)+3:]
	end := strings.Index(rest, "'")
	if end < 0 {
		return "", false
	}
	value := strings.ReplaceAll(rest[:end], `\n`, "\n")
	value = strings.ReplaceAll(value, `\'`, "'")
	return value, true
}

func stripTags(s string) string {
	var out strings.Builder
	depth := 0
	for _, r := range s {
		switch {
		case r == '<':
			depth++
		case r == '>':
			depth--
		case depth == 0:
			out.WriteRune(r)
		}
	}
	return out.String()
}
